1	package pack
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"io"
8		"sort"
9		"sync"
10		"sync/atomic"
11	
12		"github.com/go-git/go-git/v6/plumbing"
13	
14		gitwire "entire.io/internal/go-git/plumbing/format/packfile"
15		formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
16	)
17	
18	var contentBufPool sync.Pool
19	
20	func getContentBuf(size int) []byte {
21		if v := contentBufPool.Get(); v != nil {
22			bp := v.(*[]byte) //nolint:errcheck,forcetypeassert // pool only stores *[]byte
23			if cap(*bp) >= size {
24				return (*bp)[:size]
25			}
26			// Undersize. Return it to the pool so smaller future calls can
27			// reuse it instead of letting Get's drop-on-miss leak the pool.
28			contentBufPool.Put(bp)
29		}
30		return make([]byte, size)
31	}
32	
33	func putContentBuf(b []byte) {
34		b = b[:cap(b)]
35		contentBufPool.Put(&b)
36	}
37	
38	type resolvedBase struct {
39		typ     plumbing.ObjectType
40		content []byte
41	}
42	
43	type deltaResolver struct {
44		ra            io.ReaderAt
45		packSize      int64
46		entries       []scannedEntry
47		deltaByOffset map[int64]*deltaRef
48		refCount      map[int64]int
49		resolved      map[int64]resolvedBase
50		objectFormat  formatcfg.ObjectFormat
51		zr            zlibReadCloser
52	}
53	
54	// readObjectHeaderAt fetches a single pread-sized slice for an object header
55	// and parses it. Returning the inflated body offset (= offset + headerLen)
56	// and size lets callers build a SectionReader for the zlib body without a
57	// separate seek.
58	func (r *deltaResolver) readObjectHeaderAt(offset int64) (typ plumbing.ObjectType, size int64, bodyOff int64, err error) {
59		var hdr [gitwire.MaxObjectHeaderBytes]byte
60		want := int64(len(hdr))
61		if avail := r.packSize - offset; avail < want {
62			want = avail
63		}
64		n, err := r.ra.ReadAt(hdr[:want], offset)
65		if err != nil && !errors.Is(err, io.EOF) {
66			return 0, 0, 0, fmt.Errorf("read header at %d: %w", offset, err)
67		}
68		if n == 0 {
69			return 0, 0, 0, fmt.Errorf("read header at %d: empty", offset)
70		}
71		t, sz, hdrLen, err := gitwire.ParseObjectHeader(hdr[:n])
72		if err != nil {
73			return 0, 0, 0, fmt.Errorf("parse header at %d: %w", offset, err)
74		}
75		return t, sz, offset + int64(hdrLen), nil
76	}
77	
78	// resolveConfig controls how resolveDeltas runs.
79	//
80	// Workers > 1 with a non-nil ReaderAtFunc enables parallel resolution
81	// across independent delta trees, sharing the io.ReaderAt returned by
82	// the function across all workers. Otherwise resolveDeltas runs
83	// sequentially against the pack reader passed to it.
84	type resolveConfig struct {
85		Workers      int
86		ReaderAtFunc func() (ra io.ReaderAt, size int64, cleanup func(), err error)
87	}
88	
89	// resolveDeltas resolves the hashes for all delta objects in a full pack.
90	// Entries must be in pack order. Deltas must reference only in-pack objects.
91	//
92	// When cfg.Workers > 1 and cfg.ReaderAtFunc is non-nil, the function is
93	// called once (after scan, before workers dispatch) to obtain the shared
94	// io.ReaderAt, its size, and a cleanup callback. The reader must be safe
95	// for concurrent ReadAt — a memory-mapped region or *os.File qualifies.
96	func resolveDeltas(ctx context.Context, pack io.ReadSeeker, entries []scannedEntry, deltas []deltaRef, objectFormat formatcfg.ObjectFormat, cfg resolveConfig) error {
97		if err := resolveREFBaseOffsets(entries, deltas); err != nil {
98			return err
99		}
100	
101		if cfg.Workers > 1 && cfg.ReaderAtFunc != nil {
102			return resolveDeltasParallel(ctx, entries, deltas, objectFormat, cfg)
103		}
104		return resolveDeltasSequential(pack, entries, deltas, objectFormat)
105	}
106	
107	func resolveDeltasSequential(pack io.ReadSeeker, entries []scannedEntry, deltas []deltaRef, objectFormat formatcfg.ObjectFormat) error {
108		packSize, err := pack.Seek(0, io.SeekEnd)
109		if err != nil {
110			return fmt.Errorf("seek pack end: %w", err)
111		}
112		ra, ok := pack.(io.ReaderAt)
113		if !ok {
114			ra = &readSeekerAt{rs: pack}
115		}
116	
117		refCount := make(map[int64]int, len(deltas))
118		deltaByOffset := make(map[int64]*deltaRef, len(deltas))
119		for i := range deltas {
120			refCount[deltas[i].baseOffset]++
121			deltaByOffset[entries[deltas[i].entryIdx].offset] = &deltas[i]
122		}
123	
124		r := &deltaResolver{
125			ra:            ra,
126			packSize:      packSize,
127			entries:       entries,
128			deltaByOffset: deltaByOffset,
129			refCount:      refCount,
130			resolved:      make(map[int64]resolvedBase),
131			objectFormat:  objectFormat,
132		}
133		defer r.zr.release()
134	
135		for i := range deltas {
136			if err := r.resolve(&deltas[i], 0); err != nil {
137				return err
138			}
139		}
140		return nil
141	}
142	
143	// readSeekerAt adapts an io.ReadSeeker to io.ReaderAt by serializing seek+read
144	// pairs. Only used by the single-goroutine sequential fallback path; the
145	// parallel path requires a true io.ReaderAt (e.g. *os.File) for concurrent
146	// safety.
147	type readSeekerAt struct {
148		rs io.ReadSeeker
149	}
150	
151	func (s *readSeekerAt) ReadAt(p []byte, off int64) (int, error) {
152		if _, err := s.rs.Seek(off, io.SeekStart); err != nil {
153			return 0, fmt.Errorf("seek: %w", err)
154		}
155		n, err := io.ReadFull(s.rs, p)
156		if err != nil {
157			return n, fmt.Errorf("read: %w", err)
158		}
159		return n, nil
160	}
161	
162	// resolveDeltasParallel partitions deltas into independent trees and resolves
163	// each tree on its own goroutine, capped at cfg.Workers. All workers share
164	// the io.ReaderAt returned by cfg.ReaderAtFunc — concurrent ReadAt does not
165	// touch any shared seek state, and entries[i].hash writes are race-free
166	// because trees are disjoint by delta index.
167	func resolveDeltasParallel(ctx context.Context, entries []scannedEntry, deltas []deltaRef, objectFormat formatcfg.ObjectFormat, cfg resolveConfig) error {
168		ra, packSize, cleanup, err := cfg.ReaderAtFunc()
169		if err != nil {
170			return fmt.Errorf("acquire pack reader: %w", err)
171		}
172		if cleanup != nil {
173			defer cleanup()
174		}
175	
176		trees := groupDeltasByTree(entries, deltas)
177		// Largest trees first so a single fat chain doesn't become the
178		// straggler at the tail of the run.
179		sort.Slice(trees, func(i, j int) bool {
180			return len(trees[i]) > len(trees[j])
181		})
182	
183		jobs := make(chan []int, len(trees))
184		for _, tree := range trees {
185			jobs <- tree
186		}
187		close(jobs)
188	
189		workerCtx, cancel := context.WithCancel(ctx)
190		defer cancel()
191	
192		var wg sync.WaitGroup
193		var firstErr atomic.Pointer[error]
194		storeErr := func(err error) {
195			if firstErr.CompareAndSwap(nil, &err) {
196				cancel()
197			}
198		}
199	
200		for range cfg.Workers {
201			wg.Go(func() {
202				for tree := range jobs {
203					if workerCtx.Err() != nil {
204						return
205					}
206					if err := resolveTree(workerCtx, ra, packSize, entries, deltas, tree, objectFormat); err != nil {
207						storeErr(err)
208						return
209					}
210				}
211			})
212		}
213		wg.Wait()
214	
215		if e := firstErr.Load(); e != nil {
216			return *e
217		}
218		// Workers bail silently on cancellation, leaving their trees unresolved;
219		// nil here would finalize an index full of zero-hash delta entries.
220		if err := ctx.Err(); err != nil {
221			return fmt.Errorf("resolve cancelled with deltas unresolved: %w", err)
222		}
223		return nil
224	}
225	
226	func resolveTree(ctx context.Context, ra io.ReaderAt, packSize int64, entries []scannedEntry, deltas []deltaRef, treeIdx []int, objectFormat formatcfg.ObjectFormat) error {
227		refCount := make(map[int64]int, len(treeIdx))
228		deltaByOffset := make(map[int64]*deltaRef, len(treeIdx))
229		for _, i := range treeIdx {
230			refCount[deltas[i].baseOffset]++
231			deltaByOffset[entries[deltas[i].entryIdx].offset] = &deltas[i]
232		}
233	
234		r := &deltaResolver{
235			ra:            ra,
236			packSize:      packSize,
237			entries:       entries,
238			deltaByOffset: deltaByOffset,
239			refCount:      refCount,
240			resolved:      make(map[int64]resolvedBase),
241			objectFormat:  objectFormat,
242		}
243		defer r.zr.release()
244	
245		for _, i := range treeIdx {
246			if err := ctx.Err(); err != nil {
247				return fmt.Errorf("resolve cancelled: %w", err)
248			}
249			if err := r.resolve(&deltas[i], 0); err != nil {
250				return err
251			}
252		}
253		return nil
254	}
255	
256	// groupDeltasByTree returns groups of delta indices, one group per dependency
257	// tree rooted at a non-delta entry. Within each group, indices are in pack
258	// order (ascending) — the order resolveTree iterates, and the topological
259	// order resolve() depends on for base availability.
260	//
261	// Trees are independent: a delta and its transitive bases live in the same
262	// group, and no entry appears in two groups (each delta has exactly one base).
263	func groupDeltasByTree(entries []scannedEntry, deltas []deltaRef) [][]int {
264		// Delta entries indexed by their pack offset, for chain walking.
265		deltaIdxByOffset := make(map[int64]int, len(deltas))
266		for i := range deltas {
267			deltaIdxByOffset[entries[deltas[i].entryIdx].offset] = i
268		}
269	
270		// Root non-delta offset per delta. Offset 0 is a safe sentinel because
271		// the first object lives past the 12-byte pack header.
272		rootByDelta := make([]int64, len(deltas))
273		for i := range deltas {
274			if rootByDelta[i] != 0 {
275				continue
276			}
277			// Walk baseOffset chain, caching the root on every delta we cross.
278			chain := []int{i}
279			cur := deltas[i].baseOffset
280			for {
281				if di, ok := deltaIdxByOffset[cur]; ok {
282					if r := rootByDelta[di]; r != 0 {
283						for _, c := range chain {
284							rootByDelta[c] = r
285						}
286						break
287					}
288					chain = append(chain, di)
289					cur = deltas[di].baseOffset
290					continue
291				}
292				for _, c := range chain {
293					rootByDelta[c] = cur
294				}
295				break
296			}
297		}
298	
299		groups := make(map[int64][]int)
300		for i, root := range rootByDelta {
301			groups[root] = append(groups[root], i)
302		}
303		out := make([][]int, 0, len(groups))
304		for _, g := range groups {
305			out = append(out, g)
306		}
307		return out
308	}
309	
310	func (r *deltaResolver) resolve(d *deltaRef, depth int) error {
311		entry := &r.entries[d.entryIdx]
312		if !entry.hash.IsZero() {
313			return nil
314		}
315	
316		base, err := r.getContent(d.baseOffset, depth)
317		if err != nil {
318			return fmt.Errorf("resolve object at offset %d: %w", entry.offset, err)
319		}
320	
321		section := io.NewSectionReader(r.ra, d.contentOffset, r.packSize-d.contentOffset)
322		deltaReader, err := openZlibReader(section, &r.zr)
323		if err != nil {
324			return fmt.Errorf("inflate delta at %d: %w", d.contentOffset, err)
325		}
326	
327		resolved, objectHash, err := patchDeltaAndHash(base.content, deltaReader, base.typ, r.objectFormat)
328		if err != nil {
329			return fmt.Errorf("patch delta at offset %d: %w", entry.offset, err)
330		}
331		entry.hash = objectHash
332	
333		if r.refCount[entry.offset] > 0 {
334			r.resolved[entry.offset] = resolvedBase{typ: base.typ, content: resolved}
335		} else {
336			putContentBuf(resolved)
337		}
338	
339		r.refCount[d.baseOffset]--
340		if r.refCount[d.baseOffset] <= 0 {
341			if old, ok := r.resolved[d.baseOffset]; ok {
342				putContentBuf(old.content)
343			}
344			delete(r.resolved, d.baseOffset)
345		}
346	
347		return nil
348	}
349	
350	func (r *deltaResolver) getContent(offset int64, depth int) (resolvedBase, error) {
351		if cached, ok := r.resolved[offset]; ok {
352			return cached, nil
353		}
354	
355		if d, ok := r.deltaByOffset[offset]; ok {
356			// depth counts deltas crossed so far. The guard covers the hop about to
357			// be taken and does not fire on the non-delta base that ends the chain,
358			// which is how resolveAt in thin.go counts too: both admit exactly
359			// MaxDeltaChainDepth deltas.
360			if depth >= gitwire.MaxDeltaChainDepth {
361				return resolvedBase{}, fmt.Errorf("%w at offset %d: %d", gitwire.ErrDeltaChainTooDeep, offset, depth)
362			}
363			if err := r.resolve(d, depth+1); err != nil {
364				return resolvedBase{}, err
365			}
366			if cached, ok := r.resolved[offset]; ok {
367				return cached, nil
368			}
369			return resolvedBase{}, fmt.Errorf("resolved delta at offset %d not cached", offset)
370		}
371	
372		typ, size, bodyOff, err := r.readObjectHeaderAt(offset)
373		if err != nil {
374			return resolvedBase{}, err
375		}
376		if typ == gitwire.ExternalObject {
377			return resolvedBase{}, fmt.Errorf("%w: base at %d", gitwire.ErrExternalDeltaBase, offset)
378		}
379		if err := gitwire.CheckDeclaredSize(size); err != nil {
380			return resolvedBase{}, fmt.Errorf("base object at %d: %w", offset, err)
381		}
382		section := io.NewSectionReader(r.ra, bodyOff, r.packSize-bodyOff)
383		content, err := readZlibExact(section, &r.zr, size, getContentBuf(int(size)))
384		if err != nil {
385			return resolvedBase{}, fmt.Errorf("inflate base at %d: %w", offset, err)
386		}
387	
388		base := resolvedBase{typ: typ, content: content}
389		if r.refCount[offset] > 0 {
390			r.resolved[offset] = base
391		}
392		return base, nil
393	}
394	
395	// resolveREFBaseOffsets resolves REF delta base hashes to pack offsets.
396	func resolveREFBaseOffsets(entries []scannedEntry, deltas []deltaRef) error {
397		hasREF := false
398		for i := range deltas {
399			if deltas[i].isREF {
400				hasREF = true
401				break
402			}
403		}
404		if !hasREF {
405			return nil
406		}
407	
408		hashOff := make(map[plumbing.Hash]int64, len(entries)-len(deltas))
409		for i := range entries {
410			if !entries[i].hash.IsZero() {
411				hashOff[entries[i].hash] = entries[i].offset
412			}
413		}
414	
415		for i := range deltas {
416			if !deltas[i].isREF {
417				continue
418			}
419			off, ok := hashOff[deltas[i].baseHash]
420			if !ok {
421				return &ExternalBaseNotFoundError{Hash: deltas[i].baseHash}
422			}
423			deltas[i].baseOffset = off
424		}
425		return nil
426	}
427

