package pack

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"
	"sync"
	"sync/atomic"

	"github.com/go-git/go-git/v6/plumbing"

	gitwire "entire.io/internal/go-git/plumbing/format/packfile"
	formatcfg "github.com/go-git/go-git/v6/plumbing/format/config"
)

var contentBufPool sync.Pool

func getContentBuf(size int) []byte {
	if v := contentBufPool.Get(); v != nil {
		bp := v.(*[]byte) //nolint:errcheck,forcetypeassert // pool only stores *[]byte
		if cap(*bp) >= size {
			return (*bp)[:size]
		}
		// Undersize. Return it to the pool so smaller future calls can
		// reuse it instead of letting Get's drop-on-miss leak the pool.
		contentBufPool.Put(bp)
	}
	return make([]byte, size)
}

func putContentBuf(b []byte) {
	b = b[:cap(b)]
	contentBufPool.Put(&b)
}

type resolvedBase struct {
	typ     plumbing.ObjectType
	content []byte
}

type deltaResolver struct {
	ra            io.ReaderAt
	packSize      int64
	entries       []scannedEntry
	deltaByOffset map[int64]*deltaRef
	refCount      map[int64]int
	resolved      map[int64]resolvedBase
	objectFormat  formatcfg.ObjectFormat
	zr            zlibReadCloser
}

// readObjectHeaderAt fetches a single pread-sized slice for an object header
// and parses it. Returning the inflated body offset (= offset + headerLen)
// and size lets callers build a SectionReader for the zlib body without a
// separate seek.
func (r *deltaResolver) readObjectHeaderAt(offset int64) (typ plumbing.ObjectType, size int64, bodyOff int64, err error) {
	var hdr [gitwire.MaxObjectHeaderBytes]byte
	want := int64(len(hdr))
	if avail := r.packSize - offset; avail < want {
		want = avail
	}
	n, err := r.ra.ReadAt(hdr[:want], offset)
	if err != nil && !errors.Is(err, io.EOF) {
		return 0, 0, 0, fmt.Errorf("read header at %d: %w", offset, err)
	}
	if n == 0 {
		return 0, 0, 0, fmt.Errorf("read header at %d: empty", offset)
	}
	t, sz, hdrLen, err := gitwire.ParseObjectHeader(hdr[:n])
	if err != nil {
		return 0, 0, 0, fmt.Errorf("parse header at %d: %w", offset, err)
	}
	return t, sz, offset + int64(hdrLen), nil
}

// resolveConfig controls how resolveDeltas runs.
//
// Workers > 1 with a non-nil ReaderAtFunc enables parallel resolution
// across independent delta trees, sharing the io.ReaderAt returned by
// the function across all workers. Otherwise resolveDeltas runs
// sequentially against the pack reader passed to it.
type resolveConfig struct {
	Workers      int
	ReaderAtFunc func() (ra io.ReaderAt, size int64, cleanup func(), err error)
}

// resolveDeltas resolves the hashes for all delta objects in a full pack.
// Entries must be in pack order. Deltas must reference only in-pack objects.
//
// When cfg.Workers > 1 and cfg.ReaderAtFunc is non-nil, the function is
// called once (after scan, before workers dispatch) to obtain the shared
// io.ReaderAt, its size, and a cleanup callback. The reader must be safe
// for concurrent ReadAt — a memory-mapped region or *os.File qualifies.
func resolveDeltas(ctx context.Context, pack io.ReadSeeker, entries []scannedEntry, deltas []deltaRef, objectFormat formatcfg.ObjectFormat, cfg resolveConfig) error {
	if err := resolveREFBaseOffsets(entries, deltas); err != nil {
		return err
	}

	if cfg.Workers > 1 && cfg.ReaderAtFunc != nil {
		return resolveDeltasParallel(ctx, entries, deltas, objectFormat, cfg)
	}
	return resolveDeltasSequential(pack, entries, deltas, objectFormat)
}

func resolveDeltasSequential(pack io.ReadSeeker, entries []scannedEntry, deltas []deltaRef, objectFormat formatcfg.ObjectFormat) error {
	packSize, err := pack.Seek(0, io.SeekEnd)
	if err != nil {
		return fmt.Errorf("seek pack end: %w", err)
	}
	ra, ok := pack.(io.ReaderAt)
	if !ok {
		ra = &readSeekerAt{rs: pack}
	}

	refCount := make(map[int64]int, len(deltas))
	deltaByOffset := make(map[int64]*deltaRef, len(deltas))
	for i := range deltas {
		refCount[deltas[i].baseOffset]++
		deltaByOffset[entries[deltas[i].entryIdx].offset] = &deltas[i]
	}

	r := &deltaResolver{
		ra:            ra,
		packSize:      packSize,
		entries:       entries,
		deltaByOffset: deltaByOffset,
		refCount:      refCount,
		resolved:      make(map[int64]resolvedBase),
		objectFormat:  objectFormat,
	}
	defer r.zr.release()

	for i := range deltas {
		if err := r.resolve(&deltas[i], 0); err != nil {
			return err
		}
	}
	return nil
}

// readSeekerAt adapts an io.ReadSeeker to io.ReaderAt by serializing seek+read
// pairs. Only used by the single-goroutine sequential fallback path; the
// parallel path requires a true io.ReaderAt (e.g. *os.File) for concurrent
// safety.
type readSeekerAt struct {
	rs io.ReadSeeker
}

func (s *readSeekerAt) ReadAt(p []byte, off int64) (int, error) {
	if _, err := s.rs.Seek(off, io.SeekStart); err != nil {
		return 0, fmt.Errorf("seek: %w", err)
	}
	n, err := io.ReadFull(s.rs, p)
	if err != nil {
		return n, fmt.Errorf("read: %w", err)
	}
	return n, nil
}

// resolveDeltasParallel partitions deltas into independent trees and resolves
// each tree on its own goroutine, capped at cfg.Workers. All workers share
// the io.ReaderAt returned by cfg.ReaderAtFunc — concurrent ReadAt does not
// touch any shared seek state, and entries[i].hash writes are race-free
// because trees are disjoint by delta index.
func resolveDeltasParallel(ctx context.Context, entries []scannedEntry, deltas []deltaRef, objectFormat formatcfg.ObjectFormat, cfg resolveConfig) error {
	ra, packSize, cleanup, err := cfg.ReaderAtFunc()
	if err != nil {
		return fmt.Errorf("acquire pack reader: %w", err)
	}
	if cleanup != nil {
		defer cleanup()
	}

	trees := groupDeltasByTree(entries, deltas)
	// Largest trees first so a single fat chain doesn't become the
	// straggler at the tail of the run.
	sort.Slice(trees, func(i, j int) bool {
		return len(trees[i]) > len(trees[j])
	})

	jobs := make(chan []int, len(trees))
	for _, tree := range trees {
		jobs <- tree
	}
	close(jobs)

	workerCtx, cancel := context.WithCancel(ctx)
	defer cancel()

	var wg sync.WaitGroup
	var firstErr atomic.Pointer[error]
	storeErr := func(err error) {
		if firstErr.CompareAndSwap(nil, &err) {
			cancel()
		}
	}

	for range cfg.Workers {
		wg.Go(func() {
			for tree := range jobs {
				if workerCtx.Err() != nil {
					return
				}
				if err := resolveTree(workerCtx, ra, packSize, entries, deltas, tree, objectFormat); err != nil {
					storeErr(err)
					return
				}
			}
		})
	}
	wg.Wait()

	if e := firstErr.Load(); e != nil {
		return *e
	}
	// Workers bail silently on cancellation, leaving their trees unresolved;
	// nil here would finalize an index full of zero-hash delta entries.
	if err := ctx.Err(); err != nil {
		return fmt.Errorf("resolve cancelled with deltas unresolved: %w", err)
	}
	return nil
}

func resolveTree(ctx context.Context, ra io.ReaderAt, packSize int64, entries []scannedEntry, deltas []deltaRef, treeIdx []int, objectFormat formatcfg.ObjectFormat) error {
	refCount := make(map[int64]int, len(treeIdx))
	deltaByOffset := make(map[int64]*deltaRef, len(treeIdx))
	for _, i := range treeIdx {
		refCount[deltas[i].baseOffset]++
		deltaByOffset[entries[deltas[i].entryIdx].offset] = &deltas[i]
	}

	r := &deltaResolver{
		ra:            ra,
		packSize:      packSize,
		entries:       entries,
		deltaByOffset: deltaByOffset,
		refCount:      refCount,
		resolved:      make(map[int64]resolvedBase),
		objectFormat:  objectFormat,
	}
	defer r.zr.release()

	for _, i := range treeIdx {
		if err := ctx.Err(); err != nil {
			return fmt.Errorf("resolve cancelled: %w", err)
		}
		if err := r.resolve(&deltas[i], 0); err != nil {
			return err
		}
	}
	return nil
}

// groupDeltasByTree returns groups of delta indices, one group per dependency
// tree rooted at a non-delta entry. Within each group, indices are in pack
// order (ascending) — the order resolveTree iterates, and the topological
// order resolve() depends on for base availability.
//
// Trees are independent: a delta and its transitive bases live in the same
// group, and no entry appears in two groups (each delta has exactly one base).
func groupDeltasByTree(entries []scannedEntry, deltas []deltaRef) [][]int {
	// Delta entries indexed by their pack offset, for chain walking.
	deltaIdxByOffset := make(map[int64]int, len(deltas))
	for i := range deltas {
		deltaIdxByOffset[entries[deltas[i].entryIdx].offset] = i
	}

	// Root non-delta offset per delta. Offset 0 is a safe sentinel because
	// the first object lives past the 12-byte pack header.
	rootByDelta := make([]int64, len(deltas))
	for i := range deltas {
		if rootByDelta[i] != 0 {
			continue
		}
		// Walk baseOffset chain, caching the root on every delta we cross.
		chain := []int{i}
		cur := deltas[i].baseOffset
		for {
			if di, ok := deltaIdxByOffset[cur]; ok {
				if r := rootByDelta[di]; r != 0 {
					for _, c := range chain {
						rootByDelta[c] = r
					}
					break
				}
				chain = append(chain, di)
				cur = deltas[di].baseOffset
				continue
			}
			for _, c := range chain {
				rootByDelta[c] = cur
			}
			break
		}
	}

	groups := make(map[int64][]int)
	for i, root := range rootByDelta {
		groups[root] = append(groups[root], i)
	}
	out := make([][]int, 0, len(groups))
	for _, g := range groups {
		out = append(out, g)
	}
	return out
}

func (r *deltaResolver) resolve(d *deltaRef, depth int) error {
	entry := &r.entries[d.entryIdx]
	if !entry.hash.IsZero() {
		return nil
	}

	base, err := r.getContent(d.baseOffset, depth)
	if err != nil {
		return fmt.Errorf("resolve object at offset %d: %w", entry.offset, err)
	}

	section := io.NewSectionReader(r.ra, d.contentOffset, r.packSize-d.contentOffset)
	deltaReader, err := openZlibReader(section, &r.zr)
	if err != nil {
		return fmt.Errorf("inflate delta at %d: %w", d.contentOffset, err)
	}

	resolved, objectHash, err := patchDeltaAndHash(base.content, deltaReader, base.typ, r.objectFormat)
	if err != nil {
		return fmt.Errorf("patch delta at offset %d: %w", entry.offset, err)
	}
	entry.hash = objectHash

	if r.refCount[entry.offset] > 0 {
		r.resolved[entry.offset] = resolvedBase{typ: base.typ, content: resolved}
	} else {
		putContentBuf(resolved)
	}

	r.refCount[d.baseOffset]--
	if r.refCount[d.baseOffset] <= 0 {
		if old, ok := r.resolved[d.baseOffset]; ok {
			putContentBuf(old.content)
		}
		delete(r.resolved, d.baseOffset)
	}

	return nil
}

func (r *deltaResolver) getContent(offset int64, depth int) (resolvedBase, error) {
	if cached, ok := r.resolved[offset]; ok {
		return cached, nil
	}

	if d, ok := r.deltaByOffset[offset]; ok {
		// depth counts deltas crossed so far. The guard covers the hop about to
		// be taken and does not fire on the non-delta base that ends the chain,
		// which is how resolveAt in thin.go counts too: both admit exactly
		// MaxDeltaChainDepth deltas.
		if depth >= gitwire.MaxDeltaChainDepth {
			return resolvedBase{}, fmt.Errorf("%w at offset %d: %d", gitwire.ErrDeltaChainTooDeep, offset, depth)
		}
		if err := r.resolve(d, depth+1); err != nil {
			return resolvedBase{}, err
		}
		if cached, ok := r.resolved[offset]; ok {
			return cached, nil
		}
		return resolvedBase{}, fmt.Errorf("resolved delta at offset %d not cached", offset)
	}

	typ, size, bodyOff, err := r.readObjectHeaderAt(offset)
	if err != nil {
		return resolvedBase{}, err
	}
	if typ == gitwire.ExternalObject {
		return resolvedBase{}, fmt.Errorf("%w: base at %d", gitwire.ErrExternalDeltaBase, offset)
	}
	if err := gitwire.CheckDeclaredSize(size); err != nil {
		return resolvedBase{}, fmt.Errorf("base object at %d: %w", offset, err)
	}
	section := io.NewSectionReader(r.ra, bodyOff, r.packSize-bodyOff)
	content, err := readZlibExact(section, &r.zr, size, getContentBuf(int(size)))
	if err != nil {
		return resolvedBase{}, fmt.Errorf("inflate base at %d: %w", offset, err)
	}

	base := resolvedBase{typ: typ, content: content}
	if r.refCount[offset] > 0 {
		r.resolved[offset] = base
	}
	return base, nil
}

// resolveREFBaseOffsets resolves REF delta base hashes to pack offsets.
func resolveREFBaseOffsets(entries []scannedEntry, deltas []deltaRef) error {
	hasREF := false
	for i := range deltas {
		if deltas[i].isREF {
			hasREF = true
			break
		}
	}
	if !hasREF {
		return nil
	}

	hashOff := make(map[plumbing.Hash]int64, len(entries)-len(deltas))
	for i := range entries {
		if !entries[i].hash.IsZero() {
			hashOff[entries[i].hash] = entries[i].offset
		}
	}

	for i := range deltas {
		if !deltas[i].isREF {
			continue
		}
		off, ok := hashOff[deltas[i].baseHash]
		if !ok {
			return &ExternalBaseNotFoundError{Hash: deltas[i].baseHash}
		}
		deltas[i].baseOffset = off
	}
	return nil
}

