// hardening on top of upstream go-git: see Index for rationale.
//
// The same IndexOptions as Index apply: WithoutIndexFinalize + WithTempSuffix
// leave suffixed .idx-tmp/.rev-tmp for the caller to finalize (renaming the
// .idx last), so a canonical set never exposes a bare .pack with no readiness
// marker.
func WriteIndex(root *os.Root, entries []IndexEntry, packHash plumbing.Hash, objectFormat formatcfg.ObjectFormat, opts ...IndexOption) error {
	if objectFormat == formatcfg.UnsetObjectFormat {
		return errors.New("WriteIndex: objectFormat must be SHA1 or SHA256")
	}
	scanned := make([]scannedEntry, len(entries))
	for i, e := range entries {
		scanned[i] = scannedEntry{
			ordinal: uint32(i),
			offset:  e.Offset,
			crc32:   e.CRC32,
			hash:    e.Hash,
		}
	}
	cfg := newIndexConfig(root, objectFormat, opts...)
	_, err := cfg.writeIndexArtifacts(scanned, packHash)
	return err
}

func (c indexConfig) index(ctx context.Context, pack io.ReadSeeker) (plumbing.Hash, error) {
	if c.root == nil {
		return plumbing.ZeroHash, errors.New("nil root")
	}
	if pack == nil {
		return plumbing.ZeroHash, errors.New("nil pack reader")
	}

	if _, err := pack.Seek(0, io.SeekStart); err != nil {
		return plumbing.ZeroHash, fmt.Errorf("seek pack start: %w", err)
	}

	entries, deltas, _, packHash, err := c.scan(pack)
	if err != nil {
		return plumbing.ZeroHash, err
	}
	if len(deltas) > 0 {
		cfg := resolveConfig{
			Workers:      c.resolveWorkers,
			ReaderAtFunc: c.resolveReaderAt,
		}
		if err := resolveDeltas(ctx, pack, entries, deltas, c.objectFormat, cfg); err != nil {
			return plumbing.ZeroHash, err
		}
	}
	return c.writeIndexArtifacts(entries, packHash)
}

func (c indexConfig) writeIndexArtifacts(entries []scannedEntry, packHash plumbing.Hash) (plumbing.Hash, error) {
	idxName := fmt.Sprintf("pack-%s.idx", packHash)
	revName := fmt.Sprintf("pack-%s.rev", packHash)
	// Per-run suffix keeps concurrent index runs of the same pack from sharing
	// (and renaming out from under each other) the temp artifacts. finalize=false
	// callers supply it via WithTempSuffix and reuse it when finalizing; the
	// finalize=true path renames internally, so a process-unique fallback is safe.
	suffix := c.tempSuffix
	if suffix == "" && c.finalize {
		suffix = NewTempSuffix()
	}
	idxTmpName := idxName + "-tmp" + suffix
	revTmpName := revName + "-tmp" + suffix

	idxFile, err := c.root.Create(idxTmpName)
	if err != nil {
		return plumbing.ZeroHash, fmt.Errorf("create idx file: %w", err)
	}
	revFile, err := c.root.Create(revTmpName)
	if err != nil {
		_ = idxFile.Close()
		removeRootFile(c.root, idxTmpName)
		return plumbing.ZeroHash, fmt.Errorf("create rev file: %w", err)
	}

	// tempsHandled means the temps' fate is settled — either finalized into
	// their canonical names or already removed by finalizeIndexTemps' failure
	// arms — so the defer must not touch them. It is deliberately NOT named
	// "success": it is also set when finalize fails.
	tempsHandled := false
	defer func() {
		if idxFile != nil {
			_ = idxFile.Close()
		}
		if revFile != nil {
			_ = revFile.Close()
		}
		if !tempsHandled {
			removeRootFile(c.root, idxTmpName)
			removeRootFile(c.root, revTmpName)
		}
	}()

	if err := writeIndexFiles(idxFile, revFile, entries, packHash, c.objectFormat.Size()); err != nil {
		return plumbing.ZeroHash, err
	}
	idxErr := syncAndCloseFile(idxFile)
	idxFile = nil
	if idxErr != nil {
		return plumbing.ZeroHash, fmt.Errorf("sync idx temp file: %w", idxErr)
	}
	revErr := syncAndCloseFile(revFile)
	revFile = nil
	if revErr != nil {
		return plumbing.ZeroHash, fmt.Errorf("sync rev temp file: %w", revErr)
	}
	if c.finalize {
		if err := finalizeIndexTemps(c.root, packHash, suffix); err != nil {
			tempsHandled = true // its failure arms already removed the temps
			return plumbing.ZeroHash, err
		}
	}
	tempsHandled = true
	return packHash, nil
}

// finalizeIndexTemps renames a run's suffixed .idx-tmp/.rev-tmp into their
// canonical names, .idx last so it stays the readiness marker — the one
// implementation of that ordering in this package, shared by
// writeIndexArtifacts' finalize=true path and BuildPackFromThin (packfile's
// FinalizeIndexArtifacts is its path-based, non-root twin). On failure the
// attempt's remaining temps are removed; already-renamed canonical names are
// left in place (shared with any concurrent identical run, and a stray .rev
// without the .idx readiness marker is inert).
func finalizeIndexTemps(root *os.Root, packHash plumbing.Hash, suffix string) error {
	idxName := fmt.Sprintf("pack-%s.idx", packHash)
	revName := fmt.Sprintf("pack-%s.rev", packHash)
	idxTmpName := idxName + "-tmp" + suffix
	revTmpName := revName + "-tmp" + suffix

	if err := renameRootFileDurably(root, revTmpName, revName); err != nil {
		removeRootFile(root, revTmpName)
		removeRootFile(root, idxTmpName)
		return fmt.Errorf("rename rev temp file: %w", err)
	}
	if err := renameRootFileDurably(root, idxTmpName, idxName); err != nil {
		removeRootFile(root, idxTmpName)
		return fmt.Errorf("rename idx temp file: %w", err)
	}
	return nil
}

