// openZlibReader returns a zlib-decoded reader over r, reusing zr's cached
// zlib reader and bufio.Reader across calls. klauspost zlib's Reset wraps a
// non-ByteReader in a fresh bufio.Reader on every call; we pre-wrap with a
// reused bufio.Reader so the inflater sees a byteReader and skips the wrap.
func openZlibReader(r io.Reader, zr *zlibReadCloser) (io.Reader, error) {
	if zr.bufR == nil {
		zr.bufR = bufio.NewReader(r)
	} else {
		zr.bufR.Reset(r)
	}
	if zr.rc == nil {
		if v := zlibReaderPool.Get(); v != nil {
			rc := v.(io.ReadCloser) //nolint:errcheck,forcetypeassert // pool only stores io.ReadCloser
			if err := zlibResetter(rc).Reset(zr.bufR, nil); err != nil {
				return nil, fmt.Errorf("zlib reset: %w", err)
			}
			zr.rc = rc
			return zr.rc, nil
		}
		rc, err := kzlib.NewReader(zr.bufR)
		if err != nil {
			return nil, fmt.Errorf("zlib init: %w", err)
		}
		zr.rc = rc
	} else {
		if err := zlibResetter(zr.rc).Reset(zr.bufR, nil); err != nil {
			return nil, fmt.Errorf("zlib reset: %w", err)
		}
	}
	return zr.rc, nil
}

// readZlibExact inflates exactly size bytes from r. If buf has sufficient
// capacity it is reused; otherwise it is grown in place when possible.
func readZlibExact(r io.Reader, zr *zlibReadCloser, size int64, buf []byte) ([]byte, error) {
	zrReader, err := openZlibReader(r, zr)
	if err != nil {
		return nil, err
	}
	if size < 0 || size > int64(^uint(0)>>1) {
		return nil, fmt.Errorf("invalid zlib size: %d", size)
	}
	buf = slices.Grow(buf[:0], int(size))
	buf = buf[:int(size)]
	if _, err := io.ReadFull(zrReader, buf); err != nil {
		return nil, fmt.Errorf("zlib read: %w", err)
	}
	extra, err := io.Copy(io.Discard, zrReader)
	if err != nil {
		return nil, fmt.Errorf("zlib drain: %w", err)
	}
	if extra != 0 {
		return nil, fmt.Errorf("zlib size mismatch: expected %d bytes", size)
	}
	return buf, nil
}

