	// the old mmap alive. An intern hit keyed by the stale quarantine path
	// would mask exactly that. Staged packs are single-writer and
	// short-lived, so there is no sharing win to give up.
	lp, err := allocLoaded(dir, packHash, false /*rebuild*/)
	if err != nil {
		return nil, err
	}
	w.bindExternal(lp, repoID)

