// quarantine subdirectory. tmpName must already live inside the quarantine
// dir (typically via CreateTempQuarantinePack) so the indexer's rename
// targets are on the same filesystem. tr is a tail-reader (or any seekable
// reader) over the same file — production callers stream bytes into the
// temp file concurrently and pass a TailReader so indexing overlaps with
// the receive.
//
// baseFetcher is consulted when the indexer reports a thin pack; the thin
// pack is rebuilt against the fetcher's view of the repo so the staged
// result is self-contained.
//
// The caller must finish the returned Quarantined exactly once (Promote,
// Discard, or Release). Most callers should prefer StageQuarantineFrom,
// which handles the temp file + TailReader pump pipeline.
func (w *Manager) QuarantinePack(
	ctx context.Context,
	repoID repositories.ID,
	tr io.ReadSeeker,
	tmpName string,
	baseFetcher gitpack.BaseFetcher,
) (*Quarantined, error) {
	ctx, span := otel.Tracer().Start(ctx, "packfile.QuarantinePack")
	defer span.End()

	dir := w.QuarantineDir(repoID)
	if err := fsdurable.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("create quarantine dir: %w", err)
	}

	return w.indexQuarantinedStreaming(ctx, repoID, tr, tmpName, dir, baseFetcher)
}

// CreateTempQuarantinePack creates a temp file inside the repo's quarantine
// subdirectory so QuarantinePack's rename targets are on the same filesystem.
// Caller is responsible for closing the file and either passing the name
// into QuarantinePack or removing it on error.
func (w *Manager) CreateTempQuarantinePack(repoID repositories.ID) (*os.File, error) {
	dir := w.QuarantineDir(repoID)
	if err := fsdurable.MkdirAll(dir, 0o755); err != nil {
		return nil, fmt.Errorf("create quarantine dir: %w", err)
	}
	return os.CreateTemp(dir, "tmp-pack-*.pack") //nolint:wrapcheck // caller adds context
}

func (w *Manager) indexQuarantinedStreaming(
	ctx context.Context,
	repoID repositories.ID,
	tr io.ReadSeeker,
	tmpName, dir string,
	baseFetcher gitpack.BaseFetcher,
) (*Quarantined, error) {
	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, fmt.Errorf("open quarantine root: %w", err)
	}
	defer root.Close()

	// Isolate this attempt's temp artifacts so a concurrent stage of the same
	// content-addressed pack can't rename them out from under us.
	suffix := indexTempSuffix()
	packHash, parseErr := gitpack.Index(
		ctx, root, tr, w.objectFormatFor(repoID),
		gitpack.WithoutIndexFinalize(),
		gitpack.WithTempSuffix(suffix),
		gitpack.WithResolveWorkers(resolveWorkers),
		gitpack.WithResolveReaderAt(func() (io.ReaderAt, int64, func(), error) {
			f, err := os.Open(tmpName) //nolint:gosec // path from CreateTempQuarantinePack
			if err != nil {
				return nil, 0, nil, fmt.Errorf("open temp pack: %w", err)
			}
			mr, mmapErr := gobilly.Open(f)
			_ = f.Close()
			if mmapErr != nil {
				return nil, 0, nil, fmt.Errorf("mmap temp pack: %w", mmapErr)
			}
			return mr, mr.Len(), func() { _ = mr.Close() }, nil
		}),
	)
	if parseErr != nil {
		if !errors.Is(parseErr, gitpack.ErrExternalBaseNotFound) {
			return nil, fmt.Errorf("index quarantine pack: %w", parseErr)
		}
		return w.rebuildThinQuarantined(ctx, repoID, tmpName, dir, baseFetcher)
	}

	return w.stageQuarantined(repoID, tmpName, dir, packHash, suffix)
}

// rebuildThinQuarantined handles a thin pack: rebuild it in place against
// existing repo state via baseFetcher, remove the thin temp, and mmap the
// rebuilt index. The rebuilt pack has a different hash than the thin pack
// because the content differs (bases inlined); the returned Quarantined
// reports that new hash.
func (w *Manager) rebuildThinQuarantined(
	ctx context.Context,
	repoID repositories.ID,
	tmpName, dir string,
	baseFetcher gitpack.BaseFetcher,
) (*Quarantined, error) {
	root, err := os.OpenRoot(dir)
	if err != nil {
		return nil, fmt.Errorf("open quarantine root: %w", err)
	}
	defer root.Close()

	// The thin temp already lives in dir; rebuild reads it in place. Remove it
	// afterward regardless of outcome so the caller's temp-consumed invariant
	// holds (StageQuarantineFrom clears its cleanup once QuarantinePack returns).
	// No pre-finalize keep here, unlike IndexAndPromote's thin path: this
	// install targets the quarantine subdir, which the canonical orphan sweep
	// never walks.
	// Read the received trailer before the rebuild removes the thin temp. A
	// failed read only leaves the trailer unset: the stage itself does not
	// need it, and a pack without one is never parked.
	trailer, trailerErr := readTrailer(tmpName, w.objectFormatFor(repoID).Size())
	if trailerErr != nil {
		trailer = nil
	}
	newHash, buildErr := gitpack.BuildPackFromThin(ctx, root, filepath.Base(tmpName), baseFetcher, w.objectFormatFor(repoID))
	fsdurable.RemoveBestEffort(tmpName)
	if buildErr != nil {
		return nil, fmt.Errorf("rebuild thin pack: %w", buildErr)
	}

	// BuildPackFromThin finalizes the index artifacts itself (temp-until-idx
	// internally), so no FinalizeIndexArtifacts call is needed here.
	q, err := w.openQuarantined(repoID, newHash)
	if err != nil {
		return nil, fmt.Errorf("open rebuilt quarantined pack: %w", err)
	}
	q.trailer = trailer
	return q, nil
}

// readTrailer returns the last size bytes of the file at path.
func readTrailer(path string, size int) ([]byte, error) {
	f, err := os.Open(path) //nolint:gosec // path from CreateTempQuarantinePack
	if err != nil {
		return nil, err //nolint:wrapcheck // caller wraps
	}
	defer f.Close()
	buf := make([]byte, size)
	info, err := f.Stat()
	if err != nil {
		return nil, err //nolint:wrapcheck // caller wraps
	}
	if info.Size() < int64(size) {
		return nil, fmt.Errorf("pack of %d bytes is shorter than its %d-byte trailer", info.Size(), size)
	}
	if _, err := f.ReadAt(buf, info.Size()-int64(size)); err != nil {
		return nil, err //nolint:wrapcheck // caller wraps
	}
	return buf, nil
}

func (w *Manager) stageQuarantined(
	repoID repositories.ID,
	tmpName, dir string,
	packHash plumbing.Hash,
	suffix string,
) (*Quarantined, error) {
	packPath := packPathsFor(dir, packHash).Pack
	// gitpack.Index has already written this attempt's suffix-scoped
	// .idx-tmp/.rev-tmp. On any failure before we hand back the staged pack,
	// drop them: the unique suffix means no later attempt reuses (overwrites)
	// these names, so they'd otherwise accumulate. Best-effort and
	// attempt-scoped, so it can't touch a concurrent stager's temps.
	staged := false
	defer func() {
		if !staged {
			RemoveIndexTemps(dir, packHash, suffix)
		}
	}()
	if err := fsdurable.SyncPath(tmpName); err != nil {
		return nil, fmt.Errorf("sync quarantine pack: %w", err)
	}
	if err := fsdurable.Rename(tmpName, packPath); err != nil {
		return nil, fmt.Errorf("rename pack into quarantine: %w", err)
	}
	// On finalize failure the canonical pack stays put: its name is shared
	// with any concurrent identical stager, which may have just staged it and
	// still needs it. Abandoned copies are reclaimed by SweepStaleQuarantine.
	if err := FinalizeIndexArtifacts(dir, packHash, suffix); err != nil {
		return nil, fmt.Errorf("finalize quarantine index: %w", err)
	}

	q, err := w.openQuarantined(repoID, packHash)
	if err != nil {
		return nil, fmt.Errorf("open quarantined pack: %w", err)
	}
	q.trailer = packHash.Bytes()
	staged = true
	return q, nil
}

func (w *Manager) openQuarantined(
	repoID repositories.ID,
	packHash plumbing.Hash,
