// Replication is durable-intent once we begin ingesting the pack. A client
// disconnect — e.g. an intermediary resetting the already-sent connection
// during a rolling deploy — cancels the inbound request context; the
// cross-AZ provider stream-opens (a synchronous, ctx-gated gRPC call) then
// fail with "context canceled" while the local provider still stages from
// the buffered body, collapsing write quorum to the single local AZ
// (ENT-1051). Detach staging, the connectivity check, and commit from
// request cancellation — keeping the caller's deadline and trace/baggage
// values so the fanout stays bounded and observable. A client that truly
// vanishes mid-upload still aborts: the body read errors and the fanout
// returns it.
dl, hasDeadline := ctx.Deadline()
ctx = context.WithoutCancel(ctx)
if hasDeadline {
	var cancel context.CancelFunc
	ctx, cancel = context.WithDeadline(ctx, dl)
	defer cancel()
}

qs, ok := storer.(objstore.QuarantinedPushStorer)
if !ok {
	return nil, false, errors.New("storer does not support quarantined push")
}

// Empty packs (e.g. pushing a ref pointer to an already-known commit)
// carry only the 12-byte header + 20-byte trailer. Quarantine staging
// would fail because gitpack.Index produces an .idx the mmap loader
// rejects as too short, so peek the header and skip fanout + commit
// when there are no objects — just verify the proposed tips exist.
rd, numObjects, err := peekPackObjectCount(rd)
if err != nil {
	// The header guard rejects an object-count flood here, before the
	// scanner (and its EmitPackAbuse) ever runs, so classify at this gate.
	objstore.EmitPackAbuse(ctx, storer.RepoID(), err)
	return nil, false, err
}
if numObjects == 0 {
	errs, emptyErr := emptyPackConnectivityCheck(ctx, storer, rd, tips, isMirror)
	return errs, false, emptyErr
}

checkCtx, cancelCheck := context.WithCancel(ctx)
defer cancelCheck()

// checkCh is buffered(1) and the goroutine sends exactly once, so any
// abort path that calls awaitCheck after cancelCheck is guaranteed to
// observe the goroutine's exit — required because Abort/Commit will
// release the local Quarantined's mmap, which the check goroutine is
// reading via .idx lookups.
//
// signalFirstAck invokes onFirstAck synchronously, so checkStarted is
// published before the provider goroutine exits. After wg.Wait() in
// the fanout returns, awaitCheck reads a reliable value.
var checkStarted atomic.Bool
checkCh := make(chan checkOutcome, 1)
wantCheck := len(tips) > 0
onFirstAck := func(ack *objstore.ProviderAck) {
	if !wantCheck {
		return
	}
	checkStarted.Store(true)
	go func() {
		var resp *pb.ConnectivityCheckResponse
		var err error
		if ack.IsLocal {
			resp, err = runLocalConnectivityCheck(checkCtx, storer, ack, tips, isMirror)
		} else {
			resp, err = qs.ConnectivityCheckOnProvider(checkCtx, ack, tips, isMirror)
		}
		checkCh <- checkOutcome{resp: resp, err: err}
	}()
}
awaitCheck := func() (checkOutcome, bool) {
	if !checkStarted.Load() {
		return checkOutcome{}, false
	}
	return <-checkCh, true
}

result, err := qs.StorePackfileQuarantine(ctx, rd, declaredSize, onProgress, onFirstAck)
if err != nil {
	cancelCheck()
	_, _ = awaitCheck()
	return nil, false, fmt.Errorf("store packfile: %w", err)
}

// Objects are now staged in this push's own quarantine but not yet canonical.
// Test-only pause seam (nil in production): a test parks one push here to
// prove a concurrent push's connectivity check cannot resolve these staged-
// but-uncommitted objects.

