func TestScratchIndexMem(t *testing.T) {
	src := os.Getenv("SCRATCH_PACK")
	if src == "" {
		t.Skip()
	}
	workers, _ := strconv.Atoi(os.Getenv("SCRATCH_WORKERS"))
	if workers == 0 {
		workers = 4
	}
	dir := t.TempDir()
	dst := filepath.Join(dir, "tmp.pack")
	if err := os.Symlink(src, dst); err != nil {
		t.Fatal(err)
	}
	root, err := os.OpenRoot(dir)
	if err != nil {
		t.Fatal(err)
	}
	f, err := os.Open(src)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	st, _ := f.Stat()

	runtime.GC()
	samples := []metrics.Sample{{Name: "/memory/classes/heap/objects:bytes"}, {Name: "/memory/classes/total:bytes"}}
	var peakHeap, peakTotal atomic.Int64
	var phase atomic.Int32
	stop := make(chan struct{})
	done := make(chan struct{})
	go func() {
		defer close(done)
		tk := time.NewTicker(2 * time.Millisecond)
		defer tk.Stop()
		for {
			select {
			case <-stop:
				return
			case <-tk.C:
			}
			metrics.Read(samples)
			h := int64(samples[0].Value.Uint64())
			tot := int64(samples[1].Value.Uint64())
			if h > peakHeap.Load() {
				peakHeap.Store(h)
			}
			if tot > peakTotal.Load() {
				peakTotal.Store(tot)
			}
		}
	}()
	_ = phase
	start := time.Now()
	_, err = Index(context.Background(), root, f, formatcfg.SHA1,
		WithoutIndexFinalize(), WithTempSuffix(".x"),
		WithResolveWorkers(workers),
		WithResolveReaderAt(func() (io.ReaderAt, int64, func(), error) {
			g, err := os.Open(src)
			if err != nil {
				return nil, 0, nil, err
			}
			return g, st.Size(), func() { g.Close() }, nil
		}))
	close(stop)
	<-done
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("pack=%.1fMiB workers=%d elapsed=%s peakHeapObjects=%.1fMiB peakGoTotal=%.1fMiB peakResolverHeld=%.1fMiB peakResolverCount=%d",
		float64(st.Size())/(1<<20), workers, time.Since(start), float64(peakHeap.Load())/(1<<20), float64(peakTotal.Load())/(1<<20),
		float64(PeakResolvedBytes.Load())/(1<<20), PeakResolvedCount.Load())
}
